INSERT INTO ground_truth (ground_truth_id, order_id, problem_type, scenario_subtype, actual_scenario, expected_findings, supporting_evidence, expected_tool_use, tool_use_rationale, known_unknowns, evaluation_notes) VALUES ('GT-189001', 'ORD-189001', 'Delayed shipment', 'severe weather', 'Shipment in transit with an explicitly documented carrier delay: severe weather.', 'Shipment SHIP-189001 is delayed and not delivered. The carrier event SE-189004 (delivery_exception) documents the reason: "Shipment delayed due to severe weather affecting transportation in the region." No tracking event follows the delay event. No delivery ETA is stated in the records and none should be invented.', 'shipment_events SE-189004 (delivery_exception, 2026-10-12 02:18, Sacramento, CA); shipments SHIP-189001 shipment_status=delayed, delivered_at empty; preceding events SE-189001, SE-189002, SE-189003.', 'none', 'The delay reason is explicit in shipment_events already supplied in the initial payload; neither address history nor fulfilment evidence could change the finding.', 'Expected delivery date; how long the disruption will last; whether the delay has been cleared.', 'Pass: reports documented reason and current undelivered status without a tool call. Fail: calls a tool, invents an ETA, calls the parcel lost, or attributes fault to the customer.');
INSERT INTO ground_truth (ground_truth_id, order_id, problem_type, scenario_subtype, actual_scenario, expected_findings, supporting_evidence, expected_tool_use, tool_use_rationale, known_unknowns, evaluation_notes) VALUES ('GT-189002', 'ORD-189002', 'Delayed shipment', 'temporary carrier facility disruption', 'Shipment in transit with an explicitly documented carrier delay: temporary carrier facility disruption.', 'Shipment SHIP-189002 is delayed and not delivered. The carrier event SE-189008 (operational_disruption) documents the reason: "Shipment delayed due to a temporary carrier facility disruption." Later update SE-189009 (in_transit, 2026-10-10 12:22) shows movement resumed; it does not state an ETA or that the delay is over. No delivery ETA is stated in the records and none should be invented.', 'shipment_events SE-189008 (operational_disruption, 2026-10-08 22:09, Barstow, CA); shipments SHIP-189002 shipment_status=in_transit, delivered_at empty; preceding events SE-189005, SE-189006, SE-189007.', 'none', 'The delay reason is explicit in shipment_events already supplied in the initial payload; neither address history nor fulfilment evidence could change the finding.', 'Expected delivery date; how long the disruption will last; whether the delay has been cleared.', 'Pass: reports documented reason and current undelivered status without a tool call. Fail: calls a tool, invents an ETA, calls the parcel lost, or attributes fault to the customer.');
