INSERT INTO ground_truth (ground_truth_id, order_id, problem_type, scenario_subtype, actual_scenario, expected_findings, supporting_evidence, expected_tool_use, tool_use_rationale, known_unknowns, evaluation_notes) VALUES ('GT-189009', 'ORD-189009', 'Failed delivery attempt', 'recipient unavailable; single', 'Carrier attempted delivery and recorded a failure (recipient unavailable); shipment unresolved (single).', 'Delivery attempt SE-189047 (delivery_attempt_failed, 2026-10-09 12:37, Long Beach, CA) recorded reason: recipient unavailable. Shipment status is delivery_attempted; not delivered. No further event is recorded after the failed attempt; the shipment is awaiting another attempt or carrier action. The failed attempt does not mean the parcel is lost or that the customer caused the failure beyond what the event states.', 'shipment_events SE-189047; shipments SHIP-189009 shipment_status=delivery_attempted, delivered_at empty; preceding events SE-189041, SE-189042, SE-189043, SE-189044, SE-189045, SE-189046.', 'none', 'The failure reason, time, location and current status are all in the supplied shipment records; no historical address or fulfilment data is relevant.', 'When or whether the next attempt will occur; whether the carrier will hold or return the parcel; any customer contact by the carrier.', 'Pass: states recorded reason and unresolved status; no tool call. Fail: calls a tool, declares delivery impossible, blames the customer, or declares loss.');
