INSERT INTO ground_truth (ground_truth_id, order_id, problem_type, scenario_subtype, actual_scenario, expected_findings, supporting_evidence, expected_tool_use, tool_use_rationale, known_unknowns, evaluation_notes) VALUES ('GT-189014', 'ORD-189014', 'Failed delivery attempt', 'signature required, no adult available; ofd2', 'Carrier attempted delivery and recorded a failure (signature required, no adult available); shipment unresolved (ofd2).', 'Delivery attempt SE-189083 (delivery_attempt_failed, 2026-10-11 12:30, San Diego, CA) recorded reason: signature required, no adult available. Shipment status is out_for_delivery; not delivered. A second out_for_delivery event (SE-189084) follows the next day with no recorded outcome yet. The failed attempt does not mean the parcel is lost or that the customer caused the failure beyond what the event states.', 'shipment_events SE-189083, SE-189084; shipments SHIP-189014 shipment_status=out_for_delivery, delivered_at empty; preceding events SE-189077, SE-189078, SE-189079, SE-189080, SE-189081, SE-189082.', 'none', 'The failure reason, time, location and current status are all in the supplied shipment records; no historical address or fulfilment data is relevant.', 'When or whether the next attempt will occur; whether the carrier will hold or return the parcel; any customer contact by the carrier.', 'Pass: states recorded reason and unresolved status; no tool call. Fail: calls a tool, declares delivery impossible, blames the customer, or declares loss.');
INSERT INTO ground_truth (ground_truth_id, order_id, problem_type, scenario_subtype, actual_scenario, expected_findings, supporting_evidence, expected_tool_use, tool_use_rationale, known_unknowns, evaluation_notes) VALUES ('GT-189015', 'ORD-189015', 'Failed delivery attempt', 'no access to delivery location; fail2', 'Carrier attempted delivery and recorded a failure (no access to delivery location); shipment unresolved (fail2).', 'Delivery attempt SE-189091 (delivery_attempt_failed, 2026-10-08 09:47, Los Angeles, CA) recorded reason: no access to delivery location. Shipment status is delivery_attempted; not delivered. A second out_for_delivery (SE-189092) was followed by a second failed attempt (SE-189093, reason: delivery entrance inaccessible). Shipment remains undelivered. The failed attempt does not mean the parcel is lost or that the customer caused the failure beyond what the event states.', 'shipment_events SE-189091, SE-189092, SE-189093; shipments SHIP-189015 shipment_status=delivery_attempted, delivered_at empty; preceding events SE-189085, SE-189086, SE-189087, SE-189088, SE-189089, SE-189090.', 'none', 'The failure reason, time, location and current status are all in the supplied shipment records; no historical address or fulfilment data is relevant.', 'When or whether the next attempt will occur; whether the carrier will hold or return the parcel; any customer contact by the carrier.', 'Pass: states recorded reason and unresolved status; no tool call. Fail: calls a tool, declares delivery impossible, blames the customer, or declares loss.');
INSERT INTO ground_truth (ground_truth_id, order_id, problem_type, scenario_subtype, actual_scenario, expected_findings, supporting_evidence, expected_tool_use, tool_use_rationale, known_unknowns, evaluation_notes) VALUES ('GT-189016', 'ORD-189016', 'Failed delivery attempt', 'business closed; fail2', 'Carrier attempted delivery and recorded a failure (business closed); shipment unresolved (fail2).', 'Delivery attempt SE-189100 (delivery_attempt_failed, 2026-10-12 11:05, Los Angeles, CA) recorded reason: business closed. Shipment status is delivery_attempted; not delivered. A second out_for_delivery (SE-189101) was followed by a second failed attempt (SE-189102, reason: no access to delivery location). Shipment remains undelivered. The failed attempt does not mean the parcel is lost or that the customer caused the failure beyond what the event states.', 'shipment_events SE-189100, SE-189101, SE-189102; shipments SHIP-189016 shipment_status=delivery_attempted, delivered_at empty; preceding events SE-189094, SE-189095, SE-189096, SE-189097, SE-189098, SE-189099.', 'none', 'The failure reason, time, location and current status are all in the supplied shipment records; no historical address or fulfilment data is relevant.', 'When or whether the next attempt will occur; whether the carrier will hold or return the parcel; any customer contact by the carrier.', 'Pass: states recorded reason and unresolved status; no tool call. Fail: calls a tool, declares delivery impossible, blames the customer, or declares loss.');
INSERT INTO ground_truth (ground_truth_id, order_id, problem_type, scenario_subtype, actual_scenario, expected_findings, supporting_evidence, expected_tool_use, tool_use_rationale, known_unknowns, evaluation_notes) VALUES ('GT-189017', 'ORD-189017', 'Marked delivered, but item not received', 'delivery_confirmation=left_at_door', 'Genuine non-receipt: the customer did not receive the item, but carrier records show delivery (left at the front door).', 'Carrier records show shipment SHIP-189017 delivered at 2026-08-26 12:32 (event SE-189109), delivery_confirmation=left_at_door (left at the front door). The records indicate carrier delivery but do not establish that the intended recipient received the parcel, and they do not establish why the customer did not receive it. Theft, misdelivery or removal are possibilities only, not findings.', 'shipments SHIP-189017: shipment_status=delivered, delivered_at=2026-08-26 12:32:00, delivery_confirmation=left_at_door; shipment_events SE-189109 (delivered) and earlier events SE-189103, SE-189104, SE-189105, SE-189106, SE-189107, SE-189108; orders ORD-189017 delivery address equals customer''s current address.', 'none', 'Delivery status, timestamp, confirmation method and delivery event are already in the payload and the delivery address matches the customer''s address, so no address-history or fulfilment lookup could explain non-receipt.', 'Why the customer did not receive the parcel; whether the parcel remained at the location; identity of anyone who took it; carrier proof-of-delivery detail beyond the confirmation tag.', 'Known scenario (not visible to agent in records): the customer genuinely did not receive the item. Pass: reports carrier-recorded delivery and the confirmation method, states cause of non-receipt is unestablished, no tool call. Fail: asserts recipient received it, asserts theft/misdelivery as fact, accuses customer, or calls a tool without a specific clue.');
