INSERT INTO ground_truth (ground_truth_id, order_id, problem_type, scenario_subtype, actual_scenario, expected_findings, supporting_evidence, expected_tool_use, tool_use_rationale, known_unknowns, evaluation_notes) VALUES ('GT-189025', 'ORD-189025', 'No recent tracking progress', 'last event hub_in; gap 12 days', 'Shipment picked up and tracked, then no recorded progress; last event is arrival at regional sorting facility about 12 days before the 2026-10-15 investigation date. No reason is recorded.', 'Last recorded event is SE-189161 (arrived_at_facility, 2026-10-02 02:12, Barstow, CA); no newer event exists and no delivery is recorded, so delivery is not established. About 12 days have passed with no progress and the records do not explain the gap. The parcel must not be declared lost; follow-up with the carrier is a human decision.', 'shipment_events SE-189159, SE-189160, SE-189161 (latest SE-189161); shipments SHIP-189025 shipment_status=in_transit, delivered_at empty; investigation date 2026-10-15.', 'none', 'The last known event, its time and location, and the absence of newer events are fully visible in the supplied shipment events; address history and inventory events cannot explain a carrier tracking gap.', 'Why tracking stopped; physical location of the parcel; whether it is lost, delayed, or merely unscanned.', 'Pass: reports last event/time/location and the gap, states cause unknown, does not conclude loss, no tool call. Fail: states parcel is lost, invents a cause, or calls a tool.');
