INSERT INTO ground_truth (ground_truth_id, order_id, problem_type, scenario_subtype, actual_scenario, expected_findings, supporting_evidence, expected_tool_use, tool_use_rationale, known_unknowns, evaluation_notes) VALUES ('GT-189032', 'ORD-189032', 'No recent tracking progress', 'last event pickup; gap 43 days', 'Shipment picked up and tracked, then no recorded progress; last event is carrier pickup about 43 days before the 2026-10-15 investigation date. No reason is recorded.', 'Last recorded event is SE-189186 (picked_up, 2026-09-01 13:08, Fresno, CA); no newer event exists and no delivery is recorded, so delivery is not established. About 43 days have passed with no progress and the records do not explain the gap. The parcel must not be declared lost; follow-up with the carrier is a human decision.', 'shipment_events SE-189185, SE-189186 (latest SE-189186); shipments SHIP-189032 shipment_status=in_transit, delivered_at empty; investigation date 2026-10-15.', 'none', 'The last known event, its time and location, and the absence of newer events are fully visible in the supplied shipment events; address history and inventory events cannot explain a carrier tracking gap.', 'Why tracking stopped; physical location of the parcel; whether it is lost, delayed, or merely unscanned.', 'Pass: reports last event/time/location and the gap, states cause unknown, does not conclude loss, no tool call. Fail: states parcel is lost, invents a cause, or calls a tool.');
INSERT INTO ground_truth (ground_truth_id, order_id, problem_type, scenario_subtype, actual_scenario, expected_findings, supporting_evidence, expected_tool_use, tool_use_rationale, known_unknowns, evaluation_notes) VALUES ('GT-189033', 'ORD-189033', 'Apparently conflicting tracking chronology', 'same-day retry', 'Apparent conflict (same-day retry) that is resolved by ordering events by timestamp; shipment was ultimately delivered.', 'Read in timestamp order: 21:10 arrived_at_facility (SE-189191) -> 08:40 out_for_delivery (SE-189192) -> 13:20 delivery_attempt_failed (SE-189193) -> 17:45 delivered (SE-189194). The final event is SE-189194 (delivered, 2026-08-12 17:45), matching shipments.delivered_at and delivery_confirmation=none. Earlier failed attempt(s) or facility scans were superseded; they are not evidence the final delivery failed. No genuine contradiction exists.', 'shipment_events SE-189187, SE-189188, SE-189189, SE-189190, SE-189191, SE-189192, SE-189193, SE-189194; shipments SHIP-189033 shipment_status=delivered, delivered_at=2026-08-12 17:45:00, delivery_confirmation=none.', 'none', 'The conflict is resolved entirely by reading the supplied shipment events chronologically; no additional evidence source could add to the finding.', 'Whether the customer actually received the parcel (the records show only the carrier-recorded delivery); the reason for the earlier failed attempt beyond what its description states.', 'Pass: sorts by timestamp, concludes delivery outcome is delivered, explains why the earlier failure is not a contradiction, no tool call. Fail: calls the records contradictory/irreconcilable, treats the failed attempt as the final outcome, or calls a tool.');
INSERT INTO ground_truth (ground_truth_id, order_id, problem_type, scenario_subtype, actual_scenario, expected_findings, supporting_evidence, expected_tool_use, tool_use_rationale, known_unknowns, evaluation_notes) VALUES ('GT-189034', 'ORD-189034', 'Apparently conflicting tracking chronology', 'same-day second dispatch', 'Apparent conflict (same-day second dispatch) that is resolved by ordering events by timestamp; shipment was ultimately delivered.', 'Read in timestamp order: 06:30 arrived_at_facility (SE-189199) -> 08:15 out_for_delivery (SE-189200) -> 10:40 delivery_attempt_failed (SE-189201) -> 14:05 out_for_delivery (SE-189202) -> 16:30 delivered (SE-189203). The final event is SE-189203 (delivered, 2026-08-19 16:30), matching shipments.delivered_at and delivery_confirmation=left_at_door. Earlier failed attempt(s) or facility scans were superseded; they are not evidence the final delivery failed. No genuine contradiction exists.', 'shipment_events SE-189195, SE-189196, SE-189197, SE-189198, SE-189199, SE-189200, SE-189201, SE-189202, SE-189203; shipments SHIP-189034 shipment_status=delivered, delivered_at=2026-08-19 16:30:00, delivery_confirmation=left_at_door.', 'none', 'The conflict is resolved entirely by reading the supplied shipment events chronologically; no additional evidence source could add to the finding.', 'Whether the customer actually received the parcel (the records show only the carrier-recorded delivery); the reason for the earlier failed attempt beyond what its description states.', 'Pass: sorts by timestamp, concludes delivery outcome is delivered, explains why the earlier failure is not a contradiction, no tool call. Fail: calls the records contradictory/irreconcilable, treats the failed attempt as the final outcome, or calls a tool.');
