INSERT INTO ground_truth (ground_truth_id, order_id, problem_type, scenario_subtype, actual_scenario, expected_findings, supporting_evidence, expected_tool_use, tool_use_rationale, known_unknowns, evaluation_notes) VALUES ('GT-189036', 'ORD-189036', 'Apparently conflicting tracking chronology', 'late-synced facility scan stored after delivery event', 'Apparent conflict (late-synced facility scan stored after delivery event) that is resolved by ordering events by timestamp; shipment was ultimately delivered.', 'Read in timestamp order: 06:45 arrived_at_facility (SE-189219) -> 08:30 out_for_delivery (SE-189217) -> 14:10 delivered (SE-189218). The final event is SE-189218 (delivered, 2026-09-05 14:10), matching shipments.delivered_at and delivery_confirmation=left_at_mailroom. Earlier failed attempt(s) or facility scans were superseded; they are not evidence the final delivery failed. Event IDs are not in timestamp order (some scans were stored after later-timestamped events), so chronology must be taken from event_timestamp, not event_id. No genuine contradiction exists.', 'shipment_events SE-189213, SE-189214, SE-189215, SE-189216, SE-189217, SE-189218, SE-189219; shipments SHIP-189036 shipment_status=delivered, delivered_at=2026-09-05 14:10:00, delivery_confirmation=left_at_mailroom.', 'none', 'The conflict is resolved entirely by reading the supplied shipment events chronologically; no additional evidence source could add to the finding.', 'Whether the customer actually received the parcel (the records show only the carrier-recorded delivery); the reason for the earlier failed attempt beyond what its description states.', 'Pass: sorts by timestamp, concludes delivery outcome is delivered, explains why the earlier failure is not a contradiction, no tool call. Fail: calls the records contradictory/irreconcilable, treats the failed attempt as the final outcome, or calls a tool.');
