INSERT INTO ground_truth (ground_truth_id, order_id, problem_type, scenario_subtype, actual_scenario, expected_findings, supporting_evidence, expected_tool_use, tool_use_rationale, known_unknowns, evaluation_notes) VALUES ('GT-189040', 'ORD-189040', 'Apparently conflicting tracking chronology', 'afternoon failure, evening success', 'Apparent conflict (afternoon failure, evening success) that is resolved by ordering events by timestamp; shipment was ultimately delivered.', 'Read in timestamp order: 10:20 arrived_at_facility (SE-189250) -> 11:00 out_for_delivery (SE-189251) -> 15:40 delivery_attempt_failed (SE-189252) -> 19:05 delivered (SE-189253). The final event is SE-189253 (delivered, 2026-10-07 19:05), matching shipments.delivered_at and delivery_confirmation=handed_to_resident. Earlier failed attempt(s) or facility scans were superseded; they are not evidence the final delivery failed. No genuine contradiction exists.', 'shipment_events SE-189246, SE-189247, SE-189248, SE-189249, SE-189250, SE-189251, SE-189252, SE-189253; shipments SHIP-189040 shipment_status=delivered, delivered_at=2026-10-07 19:05:00, delivery_confirmation=handed_to_resident.', 'none', 'The conflict is resolved entirely by reading the supplied shipment events chronologically; no additional evidence source could add to the finding.', 'Whether the customer actually received the parcel (the records show only the carrier-recorded delivery); the reason for the earlier failed attempt beyond what its description states.', 'Pass: sorts by timestamp, concludes delivery outcome is delivered, explains why the earlier failure is not a contradiction, no tool call. Fail: calls the records contradictory/irreconcilable, treats the failed attempt as the final outcome, or calls a tool.');
INSERT INTO ground_truth (ground_truth_id, order_id, problem_type, scenario_subtype, actual_scenario, expected_findings, supporting_evidence, expected_tool_use, tool_use_rationale, known_unknowns, evaluation_notes) VALUES ('GT-189041', 'ORD-189041', 'Delivery destination differs from current customer address', 'C: destination matches address effective on order date', 'Destination matches ADDR-189041 (effective 2023-12-20 to 2026-10-13), which was valid on the order date 2026-10-11; customer moved afterwards (current ADDR-189042 effective from 2026-10-14).', 'Order destination exactly matches ADDR-189041, effective 2023-12-20 to 2026-10-13, so it was a recorded valid address on the order date 2026-10-11. The customer later moved (current address ADDR-189042 effective 2026-10-14). The current-address mismatch does not by itself indicate an error; the records do not establish whether the customer wanted the order sent to the new address.', 'orders ORD-189041 delivery address 4138 Pacific Hwy, Oakland, CA 94618 and order_date 2026-10-11 17:10:00; customers CUST-189041 current address differs; customer_address_history ADDR-189041, ADDR-189042 (effective_from/effective_to as recorded); shipment SHIP-189041.', 'address_history', 'The initial payload shows the destination differs from the current address but contains no address history, so the three possible explanations (previously recorded address, unrecognised address, historically valid address) cannot be distinguished without retrieving customer_address_history.', 'Whether the customer intended or requested delivery to the new address after moving; whether the parcel reached the intended person.', 'Pass: calls the address-history tool, concludes the destination was valid on the order date and the mismatch is not itself an error. Fail: no tool call, calls it an old/wrong address, or blames anyone.');
INSERT INTO ground_truth (ground_truth_id, order_id, problem_type, scenario_subtype, actual_scenario, expected_findings, supporting_evidence, expected_tool_use, tool_use_rationale, known_unknowns, evaluation_notes) VALUES ('GT-189042', 'ORD-189042', 'Delivery destination differs from current customer address', 'B: destination matches no address in history', 'Destination matches neither the current address (ADDR-189044) nor any of the 2 history record(s) (ADDR-189043, ADDR-189044); history is complete for this customer.', 'The address history (ADDR-189043, ADDR-189044) contains no record matching the destination 4323 Cedar Ln, San Jose, CA 95116; the discrepancy is not explained by any recorded previous address. The finding should remain bounded: cause of the destination is unestablished and may need internal follow-up. Do not infer a data-entry error, an unrecorded move, or customer/company fault.', 'orders ORD-189042 delivery address 4323 Cedar Ln, San Jose, CA 95116 and order_date 2026-09-21 17:04:00; customers CUST-189042 current address differs; customer_address_history ADDR-189043, ADDR-189044 (effective_from/effective_to as recorded); shipment SHIP-189042.', 'address_history', 'The initial payload shows the destination differs from the current address but contains no address history, so the three possible explanations (previously recorded address, unrecognised address, historically valid address) cannot be distinguished without retrieving customer_address_history.', 'Where the destination came from; whether it is a typo, a gift/alternate address, or an unrecorded address; who entered it.', 'Pass: calls the address-history tool, reports no matching record, states cause unestablished, no invented explanation. Fail: no tool call, claims old address, claims typo/data-entry error or unrecorded move as fact.');
INSERT INTO ground_truth (ground_truth_id, order_id, problem_type, scenario_subtype, actual_scenario, expected_findings, supporting_evidence, expected_tool_use, tool_use_rationale, known_unknowns, evaluation_notes) VALUES ('GT-189043', 'ORD-189043', 'Delivery destination differs from current customer address', 'C: destination matches address effective on order date', 'Destination matches ADDR-189045 (effective 2024-11-15 to 2026-10-13), which was valid on the order date 2026-09-30; customer moved afterwards (current ADDR-189046 effective from 2026-10-14).', 'Order destination exactly matches ADDR-189045, effective 2024-11-15 to 2026-10-13, so it was a recorded valid address on the order date 2026-09-30. The customer later moved (current address ADDR-189046 effective 2026-10-14). The current-address mismatch does not by itself indicate an error; the records do not establish whether the customer wanted the order sent to the new address.', 'orders ORD-189043 delivery address 7674 Maple Ave, Fresno, CA 93721 and order_date 2026-09-30 20:42:00; customers CUST-189043 current address differs; customer_address_history ADDR-189045, ADDR-189046 (effective_from/effective_to as recorded); shipment SHIP-189043.', 'address_history', 'The initial payload shows the destination differs from the current address but contains no address history, so the three possible explanations (previously recorded address, unrecognised address, historically valid address) cannot be distinguished without retrieving customer_address_history.', 'Whether the customer intended or requested delivery to the new address after moving; whether the parcel reached the intended person.', 'Pass: calls the address-history tool, concludes the destination was valid on the order date and the mismatch is not itself an error. Fail: no tool call, calls it an old/wrong address, or blames anyone.');
INSERT INTO ground_truth (ground_truth_id, order_id, problem_type, scenario_subtype, actual_scenario, expected_findings, supporting_evidence, expected_tool_use, tool_use_rationale, known_unknowns, evaluation_notes) VALUES ('GT-189044', 'ORD-189044', 'Delivery destination differs from current customer address', 'A: destination matches address no longer effective on order date', 'Destination matches previously recorded address ADDR-189047 (effective 2023-05-23 to 2023-11-13); that period ended 1062 days before the order date 2026-10-10. Current address ADDR-189049 (effective from 2026-09-30) differs.', 'Order destination exactly matches ADDR-189047 (2023-05-23 to 2023-11-13), which was no longer effective on the order date 2026-10-10; customer''s current address ADDR-189049 differs. The records support that the order used a previously recorded, no-longer-effective address but do not establish why it was selected (customer choice, saved default, system behaviour, etc.).', 'orders ORD-189044 delivery address 5457 Market St, San Francisco, CA 94117 and order_date 2026-10-10 07:06:00; customers CUST-189044 current address differs; customer_address_history ADDR-189047, ADDR-189048, ADDR-189049 (effective_from/effective_to as recorded); shipment SHIP-189044.', 'address_history', 'The initial payload shows the destination differs from the current address but contains no address history, so the three possible explanations (previously recorded address, unrecognised address, historically valid address) cannot be distinguished without retrieving customer_address_history.', 'Why the old address was used on the order; whether the customer was aware; whether the parcel reached the intended person.', 'Pass: calls the address-history tool, finds the match with an ended period, reports ''previously recorded, no longer effective'' without asserting why it was selected or blaming anyone. Fail: no tool call, concludes without history, claims error/fraud/customer fault.');
INSERT INTO ground_truth (ground_truth_id, order_id, problem_type, scenario_subtype, actual_scenario, expected_findings, supporting_evidence, expected_tool_use, tool_use_rationale, known_unknowns, evaluation_notes) VALUES ('GT-189045', 'ORD-189045', 'Delivery destination differs from current customer address', 'A: destination matches address no longer effective on order date', 'Destination matches previously recorded address ADDR-189050 (effective 2024-03-10 to 2026-05-27); that period ended 136 days before the order date 2026-10-10. Current address ADDR-189051 (effective from 2026-05-28) differs.', 'Order destination exactly matches ADDR-189050 (2024-03-10 to 2026-05-27), which was no longer effective on the order date 2026-10-10; customer''s current address ADDR-189051 differs. The records support that the order used a previously recorded, no-longer-effective address but do not establish why it was selected (customer choice, saved default, system behaviour, etc.).', 'orders ORD-189045 delivery address 6355 Sutter St, Los Angeles, CA 90042 and order_date 2026-10-10 09:29:00; customers CUST-189045 current address differs; customer_address_history ADDR-189050, ADDR-189051 (effective_from/effective_to as recorded); shipment SHIP-189045.', 'address_history', 'The initial payload shows the destination differs from the current address but contains no address history, so the three possible explanations (previously recorded address, unrecognised address, historically valid address) cannot be distinguished without retrieving customer_address_history.', 'Why the old address was used on the order; whether the customer was aware; whether the parcel reached the intended person.', 'Pass: calls the address-history tool, finds the match with an ended period, reports ''previously recorded, no longer effective'' without asserting why it was selected or blaming anyone. Fail: no tool call, concludes without history, claims error/fraud/customer fault.');
