INSERT INTO ground_truth (ground_truth_id, order_id, problem_type, scenario_subtype, actual_scenario, expected_findings, supporting_evidence, expected_tool_use, tool_use_rationale, known_unknowns, evaluation_notes) VALUES ('GT-189047', 'ORD-189047', 'Delivery destination differs from current customer address', 'C: destination matches address effective on order date', 'Destination matches ADDR-189055 (effective 2025-01-15 to 2026-10-13), which was valid on the order date 2026-09-29; customer moved afterwards (current ADDR-189056 effective from 2026-10-14).', 'Order destination exactly matches ADDR-189055, effective 2025-01-15 to 2026-10-13, so it was a recorded valid address on the order date 2026-09-29. The customer later moved (current address ADDR-189056 effective 2026-10-14). The current-address mismatch does not by itself indicate an error; the records do not establish whether the customer wanted the order sent to the new address.', 'orders ORD-189047 delivery address 1085 Market St, Oakland, CA 94618 and order_date 2026-09-29 16:00:00; customers CUST-189047 current address differs; customer_address_history ADDR-189054, ADDR-189055, ADDR-189056 (effective_from/effective_to as recorded); shipment SHIP-189047.', 'address_history', 'The initial payload shows the destination differs from the current address but contains no address history, so the three possible explanations (previously recorded address, unrecognised address, historically valid address) cannot be distinguished without retrieving customer_address_history.', 'Whether the customer intended or requested delivery to the new address after moving; whether the parcel reached the intended person.', 'Pass: calls the address-history tool, concludes the destination was valid on the order date and the mismatch is not itself an error. Fail: no tool call, calls it an old/wrong address, or blames anyone.');
