INSERT INTO ground_truth (ground_truth_id, order_id, problem_type, scenario_subtype, actual_scenario, expected_findings, supporting_evidence, expected_tool_use, tool_use_rationale, known_unknowns, evaluation_notes) VALUES ('GT-189051', 'ORD-189051', 'Delivery destination differs from current customer address', 'B: destination matches no address in history', 'Destination matches neither the current address (ADDR-189064) nor any of the 1 history record(s) (ADDR-189064); history is complete for this customer.', 'The address history (ADDR-189064) contains no record matching the destination 7299 Cedar Ln, Los Angeles, CA 90042; the discrepancy is not explained by any recorded previous address. The finding should remain bounded: cause of the destination is unestablished and may need internal follow-up. Do not infer a data-entry error, an unrecorded move, or customer/company fault.', 'orders ORD-189051 delivery address 7299 Cedar Ln, Los Angeles, CA 90042 and order_date 2026-09-26 12:06:00; customers CUST-189051 current address differs; customer_address_history ADDR-189064 (effective_from/effective_to as recorded); shipment SHIP-189051.', 'address_history', 'The initial payload shows the destination differs from the current address but contains no address history, so the three possible explanations (previously recorded address, unrecognised address, historically valid address) cannot be distinguished without retrieving customer_address_history.', 'Where the destination came from; whether it is a typo, a gift/alternate address, or an unrecorded address; who entered it.', 'Pass: calls the address-history tool, reports no matching record, states cause unestablished, no invented explanation. Fail: no tool call, claims old address, claims typo/data-entry error or unrecorded move as fact. Near-miss destination (similar to a recorded address) must not be treated as proof of an error.');
