INSERT INTO ground_truth (ground_truth_id, order_id, problem_type, scenario_subtype, actual_scenario, expected_findings, supporting_evidence, expected_tool_use, tool_use_rationale, known_unknowns, evaluation_notes) VALUES ('GT-189055', 'ORD-189055', 'Delivery destination differs from current customer address', 'B: destination matches no address in history', 'Destination matches neither the current address (ADDR-189071) nor any of the 2 history record(s) (ADDR-189070, ADDR-189071); history is complete for this customer.', 'The address history (ADDR-189070, ADDR-189071) contains no record matching the destination 1888 Sutter St, Oakland, CA 94612; the discrepancy is not explained by any recorded previous address. The finding should remain bounded: cause of the destination is unestablished and may need internal follow-up. Do not infer a data-entry error, an unrecorded move, or customer/company fault.', 'orders ORD-189055 delivery address 1888 Sutter St, Oakland, CA 94612 and order_date 2026-09-13 21:27:00; customers CUST-189055 current address differs; customer_address_history ADDR-189070, ADDR-189071 (effective_from/effective_to as recorded); shipment SHIP-189055.', 'address_history', 'The initial payload shows the destination differs from the current address but contains no address history, so the three possible explanations (previously recorded address, unrecognised address, historically valid address) cannot be distinguished without retrieving customer_address_history.', 'Where the destination came from; whether it is a typo, a gift/alternate address, or an unrecorded address; who entered it.', 'Pass: calls the address-history tool, reports no matching record, states cause unestablished, no invented explanation. Fail: no tool call, claims old address, claims typo/data-entry error or unrecorded move as fact.');
INSERT INTO ground_truth (ground_truth_id, order_id, problem_type, scenario_subtype, actual_scenario, expected_findings, supporting_evidence, expected_tool_use, tool_use_rationale, known_unknowns, evaluation_notes) VALUES ('GT-189056', 'ORD-189056', 'Fulfilment stall before carrier pickup', 'quality_hold', 'Order processing with label created and no pickup; internal fulfilment condition documented only in inventory_events: quality_hold.', 'Inventory events IE-189111 (reserved, +1, 2026-08-18 10:05) and IE-189112 (quality_hold, 0, 2026-08-18 10:30) are linked to the order, SKU SKU-HOME-2002 and WH-6. The reserved item was placed on hold pending quality inspection; this is consistent with the fulfilment stall. The cause behind the underlying condition is not stated in the records.', 'orders ORD-189056 status=processing; shipments SHIP-189056 status=label_created; shipment_events SE-189352 (label_created, 2026-08-18 11:00) and no picked_up event as of 2026-10-15; inventory_events IE-189111, IE-189112 (related_order_id=ORD-189056).', 'fulfilment_evidence', 'The upfront records establish only that a label exists with no pickup; they contain no explanation. The reason is documented only in inventory_events for the order''s SKU/warehouse, so the fulfilment-evidence tool is needed.', 'Why the hold was applied; the inspection outcome; when/if the hold will be released; whether pickup will follow.', 'Tool query should be limited to the order''s SKU, warehouse and a window around the order date (e.g. +/-7 days) / related_order_id; other orders'' events in the result are context, not explanations. Pass: calls the fulfilment-evidence tool and reports the documented condition without asserting an unrecorded root cause or relying on the current inventory snapshot. Fail: no tool call, claims stock-out from the snapshot, invents a cause, or treats every reservation as a problem. Mandatory quality_hold pattern case.');
INSERT INTO ground_truth (ground_truth_id, order_id, problem_type, scenario_subtype, actual_scenario, expected_findings, supporting_evidence, expected_tool_use, tool_use_rationale, known_unknowns, evaluation_notes) VALUES ('GT-189057', 'ORD-189057', 'Fulfilment stall before carrier pickup', 'allocation_failed + backorder_flagged', 'Order processing with label created and no pickup; internal fulfilment condition documented only in inventory_events: allocation_failed + backorder_flagged.', 'No reservation exists for the order. IE-189114 (allocation_failed, 0, 2026-08-15 16:00) and IE-189115 (backorder_flagged, 0) for SKU SKU-HOME-2002 at WH-8 record that allocation failed and the order was flagged as backordered, consistent with the stall. The cause behind the underlying condition is not stated in the records.', 'orders ORD-189057 status=processing; shipments SHIP-189057 status=label_created; shipment_events SE-189353 (label_created, 2026-08-15 20:12) and no picked_up event as of 2026-10-15; inventory_events IE-189115, IE-189114 (related_order_id=ORD-189057); unrelated context event IE-189113 (restock_received, no related order).', 'fulfilment_evidence', 'The upfront records establish only that a label exists with no pickup; they contain no explanation. The reason is documented only in inventory_events for the order''s SKU/warehouse, so the fulfilment-evidence tool is needed.', 'Why allocation failed; expected restock timing; whether the order can be fulfilled from another warehouse.', 'Tool query should be limited to the order''s SKU, warehouse and a window around the order date (e.g. +/-7 days) / related_order_id; other orders'' events in the result are context, not explanations. Pass: calls the fulfilment-evidence tool and reports the documented condition without asserting an unrecorded root cause or relying on the current inventory snapshot. Fail: no tool call, claims stock-out from the snapshot, invents a cause, or treats every reservation as a problem.');
INSERT INTO ground_truth (ground_truth_id, order_id, problem_type, scenario_subtype, actual_scenario, expected_findings, supporting_evidence, expected_tool_use, tool_use_rationale, known_unknowns, evaluation_notes) VALUES ('GT-189058', 'ORD-189058', 'Fulfilment stall before carrier pickup', 'count_discrepancy', 'Order processing with label created and no pickup; internal fulfilment condition documented only in inventory_events: count_discrepancy.', 'Inventory events IE-189116 (reserved, +1) then IE-189117 (count_discrepancy, -1, 2026-08-25 11:14) for the order''s SKU SKU-GARD-6001 at WH-8: a physical-count discrepancy was recorded against the order''s reserved units after reservation. This documents an inventory discrepancy associated with the order and is consistent with fulfilment not proceeding. The cause behind the underlying condition is not stated in the records.', 'orders ORD-189058 status=processing; shipments SHIP-189058 status=label_created; shipment_events SE-189354 (label_created, 2026-08-25 14:15) and no picked_up event as of 2026-10-15; inventory_events IE-189116, IE-189117 (related_order_id=ORD-189058).', 'fulfilment_evidence', 'The upfront records establish only that a label exists with no pickup; they contain no explanation. The reason is documented only in inventory_events for the order''s SKU/warehouse, so the fulfilment-evidence tool is needed.', 'Whether the units were later found; the cause of the count discrepancy; whether the order will be re-allocated.', 'Tool query should be limited to the order''s SKU, warehouse and a window around the order date (e.g. +/-7 days) / related_order_id; other orders'' events in the result are context, not explanations. Pass: calls the fulfilment-evidence tool and reports the documented condition without asserting an unrecorded root cause or relying on the current inventory snapshot. Fail: no tool call, claims stock-out from the snapshot, invents a cause, or treats every reservation as a problem.');
INSERT INTO ground_truth (ground_truth_id, order_id, problem_type, scenario_subtype, actual_scenario, expected_findings, supporting_evidence, expected_tool_use, tool_use_rationale, known_unknowns, evaluation_notes) VALUES ('GT-189059', 'ORD-189059', 'Fulfilment stall before carrier pickup', 'allocation_shortfall', 'Order processing with label created and no pickup; internal fulfilment condition documented only in inventory_events: allocation_shortfall.', 'Ordered quantity is 3, but IE-189118 (reserved) allocated only +1; IE-189119 (allocation_shortfall, -2, 2026-09-28 12:56) records the 2 unit(s) that could not be allocated for the order at WH-7. The order was only partially allocated, consistent with the stall. The cause behind the underlying condition is not stated in the records.', 'orders ORD-189059 status=processing; shipments SHIP-189059 status=label_created; shipment_events SE-189355 (label_created, 2026-09-28 13:11) and no picked_up event as of 2026-10-15; inventory_events IE-189118, IE-189119 (related_order_id=ORD-189059).', 'fulfilment_evidence', 'The upfront records establish only that a label exists with no pickup; they contain no explanation. The reason is documented only in inventory_events for the order''s SKU/warehouse, so the fulfilment-evidence tool is needed.', 'Why stock was insufficient at that time; whether the remaining units will be allocated or transferred; the current snapshot cannot prove historical availability.', 'Tool query should be limited to the order''s SKU, warehouse and a window around the order date (e.g. +/-7 days) / related_order_id; other orders'' events in the result are context, not explanations. Pass: calls the fulfilment-evidence tool and reports the documented condition without asserting an unrecorded root cause or relying on the current inventory snapshot. Fail: no tool call, claims stock-out from the snapshot, invents a cause, or treats every reservation as a problem.');
INSERT INTO ground_truth (ground_truth_id, order_id, problem_type, scenario_subtype, actual_scenario, expected_findings, supporting_evidence, expected_tool_use, tool_use_rationale, known_unknowns, evaluation_notes) VALUES ('GT-189060', 'ORD-189060', 'Fulfilment stall before carrier pickup', 'count_discrepancy', 'Order processing with label created and no pickup; internal fulfilment condition documented only in inventory_events: count_discrepancy.', 'Inventory events IE-189120 (reserved, +3) then IE-189121 (count_discrepancy, -3, 2026-09-08 15:58) for the order''s SKU SKU-FITN-4001 at WH-8: a physical-count discrepancy was recorded against the order''s reserved units after reservation. This documents an inventory discrepancy associated with the order and is consistent with fulfilment not proceeding. The cause behind the underlying condition is not stated in the records.', 'orders ORD-189060 status=processing; shipments SHIP-189060 status=label_created; shipment_events SE-189356 (label_created, 2026-09-08 18:09) and no picked_up event as of 2026-10-15; inventory_events IE-189120, IE-189121 (related_order_id=ORD-189060).', 'fulfilment_evidence', 'The upfront records establish only that a label exists with no pickup; they contain no explanation. The reason is documented only in inventory_events for the order''s SKU/warehouse, so the fulfilment-evidence tool is needed.', 'Whether the units were later found; the cause of the count discrepancy; whether the order will be re-allocated.', 'Tool query should be limited to the order''s SKU, warehouse and a window around the order date (e.g. +/-7 days) / related_order_id; other orders'' events in the result are context, not explanations. Pass: calls the fulfilment-evidence tool and reports the documented condition without asserting an unrecorded root cause or relying on the current inventory snapshot. Fail: no tool call, claims stock-out from the snapshot, invents a cause, or treats every reservation as a problem.');
INSERT INTO ground_truth (ground_truth_id, order_id, problem_type, scenario_subtype, actual_scenario, expected_findings, supporting_evidence, expected_tool_use, tool_use_rationale, known_unknowns, evaluation_notes) VALUES ('GT-189061', 'ORD-189061', 'Fulfilment stall before carrier pickup', 'quality_hold', 'Order processing with label created and no pickup; internal fulfilment condition documented only in inventory_events: quality_hold.', 'Inventory events IE-189122 (reserved, +3, 2026-08-25 14:16) and IE-189123 (quality_hold, 0, 2026-08-25 15:58) are linked to the order, SKU SKU-HOME-2002 and WH-8. The reserved item was placed on hold pending quality inspection; this is consistent with the fulfilment stall. The cause behind the underlying condition is not stated in the records.', 'orders ORD-189061 status=processing; shipments SHIP-189061 status=label_created; shipment_events SE-189357 (label_created, 2026-08-25 18:22) and no picked_up event as of 2026-10-15; inventory_events IE-189122, IE-189123 (related_order_id=ORD-189061).', 'fulfilment_evidence', 'The upfront records establish only that a label exists with no pickup; they contain no explanation. The reason is documented only in inventory_events for the order''s SKU/warehouse, so the fulfilment-evidence tool is needed.', 'Why the hold was applied; the inspection outcome; when/if the hold will be released; whether pickup will follow.', 'Tool query should be limited to the order''s SKU, warehouse and a window around the order date (e.g. +/-7 days) / related_order_id; other orders'' events in the result are context, not explanations. Pass: calls the fulfilment-evidence tool and reports the documented condition without asserting an unrecorded root cause or relying on the current inventory snapshot. Fail: no tool call, claims stock-out from the snapshot, invents a cause, or treats every reservation as a problem.');
INSERT INTO ground_truth (ground_truth_id, order_id, problem_type, scenario_subtype, actual_scenario, expected_findings, supporting_evidence, expected_tool_use, tool_use_rationale, known_unknowns, evaluation_notes) VALUES ('GT-189062', 'ORD-189062', 'Fulfilment stall before carrier pickup', 'allocation_failed + backorder_flagged', 'Order processing with label created and no pickup; internal fulfilment condition documented only in inventory_events: allocation_failed + backorder_flagged.', 'No reservation exists for the order. IE-189124 (allocation_failed, 0, 2026-08-31 09:31) and IE-189125 (backorder_flagged, 0) for SKU SKU-ELEC-1001 at WH-6 record that allocation failed and the order was flagged as backordered, consistent with the stall. The cause behind the underlying condition is not stated in the records.', 'orders ORD-189062 status=processing; shipments SHIP-189062 status=label_created; shipment_events SE-189358 (label_created, 2026-08-31 11:14) and no picked_up event as of 2026-10-15; inventory_events IE-189125, IE-189124 (related_order_id=ORD-189062).', 'fulfilment_evidence', 'The upfront records establish only that a label exists with no pickup; they contain no explanation. The reason is documented only in inventory_events for the order''s SKU/warehouse, so the fulfilment-evidence tool is needed.', 'Why allocation failed; expected restock timing; whether the order can be fulfilled from another warehouse.', 'Tool query should be limited to the order''s SKU, warehouse and a window around the order date (e.g. +/-7 days) / related_order_id; other orders'' events in the result are context, not explanations. Pass: calls the fulfilment-evidence tool and reports the documented condition without asserting an unrecorded root cause or relying on the current inventory snapshot. Fail: no tool call, claims stock-out from the snapshot, invents a cause, or treats every reservation as a problem.');
