-- Velora Market synthetic dataset (PostgreSQL). Operational schema unchanged; input_data and ground_truth are separate evaluation tables.
BEGIN;
DROP TABLE IF EXISTS ground_truth CASCADE;
DROP TABLE IF EXISTS input_data CASCADE;
DROP TABLE IF EXISTS warehouses CASCADE;
DROP TABLE IF EXISTS inventory CASCADE;
DROP TABLE IF EXISTS inventory_events CASCADE;
DROP TABLE IF EXISTS shipment_events CASCADE;
DROP TABLE IF EXISTS shipments CASCADE;
DROP TABLE IF EXISTS orders CASCADE;
DROP TABLE IF EXISTS customer_address_history CASCADE;
DROP TABLE IF EXISTS customers CASCADE;
CREATE TABLE customers (
  customer_id VARCHAR(255) PRIMARY KEY,
  name VARCHAR(255),
  email VARCHAR(255),
  current_street VARCHAR(255),
  current_city VARCHAR(255),
  current_state VARCHAR(255),
  current_zip VARCHAR(255),
  account_created_at DATE
);
CREATE TABLE customer_address_history (
  address_history_id VARCHAR(255) PRIMARY KEY,
  customer_id VARCHAR(255),
  street VARCHAR(255),
  city VARCHAR(255),
  state VARCHAR(255),
  zip VARCHAR(255),
  effective_from DATE,
  effective_to DATE,
  FOREIGN KEY (customer_id) REFERENCES customers(customer_id)
);
CREATE TABLE orders (
  order_id VARCHAR(255) PRIMARY KEY,
  customer_id VARCHAR(255),
  order_date TIMESTAMP,
  sku VARCHAR(255),
  product_name VARCHAR(255),
  quantity INTEGER,
  unit_price NUMERIC(10,2),
  order_value NUMERIC(10,2),
  delivery_street VARCHAR(255),
  delivery_city VARCHAR(255),
  delivery_state VARCHAR(255),
  delivery_zip VARCHAR(255),
  order_status VARCHAR(255),
  fulfilled_from_warehouse_id VARCHAR(255),
  FOREIGN KEY (customer_id) REFERENCES customers(customer_id),
  FOREIGN KEY (fulfilled_from_warehouse_id) REFERENCES warehouses(warehouse_id)
);
CREATE TABLE shipments (
  shipment_id VARCHAR(255) PRIMARY KEY,
  order_id VARCHAR(255),
  carrier VARCHAR(255),
  tracking_number VARCHAR(255),
  ship_date TIMESTAMP,
  shipment_status VARCHAR(255),
  delivered_at TIMESTAMP,
  delivery_confirmation VARCHAR(255),
  FOREIGN KEY (order_id) REFERENCES orders(order_id)
);
CREATE TABLE shipment_events (
  event_id VARCHAR(255) PRIMARY KEY,
  shipment_id VARCHAR(255),
  event_type VARCHAR(255),
  event_timestamp TIMESTAMP,
  location VARCHAR(255),
  description VARCHAR(255),
  FOREIGN KEY (shipment_id) REFERENCES shipments(shipment_id)
);
CREATE TABLE inventory_events (
  event_id VARCHAR(255) PRIMARY KEY,
  sku VARCHAR(255),
  warehouse_id VARCHAR(255),
  event_type VARCHAR(255),
  quantity_change INTEGER,
  event_timestamp TIMESTAMP,
  related_order_id VARCHAR(255),
  FOREIGN KEY (related_order_id) REFERENCES orders(order_id)
);
CREATE TABLE inventory (
  inventory_id VARCHAR(255) PRIMARY KEY,
  sku VARCHAR(255),
  warehouse_id VARCHAR(255),
  stock_quantity INTEGER,
  reserved_quantity INTEGER
);
CREATE TABLE warehouses (
  warehouse_id VARCHAR(255) PRIMARY KEY,
  name VARCHAR(255),
  city VARCHAR(255),
  state VARCHAR(255)
);
CREATE TABLE input_data (
  input_id VARCHAR(2000) PRIMARY KEY,
  order_id VARCHAR(2000),
  problem_description TEXT,
  input_payload JSONB,
  FOREIGN KEY (order_id) REFERENCES orders(order_id)
);
CREATE TABLE ground_truth (
  ground_truth_id VARCHAR(2000) PRIMARY KEY,
  order_id VARCHAR(2000),
  problem_type VARCHAR(2000),
  scenario_subtype TEXT,
  actual_scenario TEXT,
  expected_findings TEXT,
  supporting_evidence TEXT,
  expected_tool_use VARCHAR(2000),
  tool_use_rationale TEXT,
  known_unknowns TEXT,
  evaluation_notes TEXT,
  FOREIGN KEY (order_id) REFERENCES orders(order_id)
);
COMMIT;
